package com.bank.statement;

// A rendered statement PDF. Holds a simulated native font buffer that must
// be freed after the PDF is reclaimed (phantom-reference cleanup).
class RenderedPdf {
    private final String accountId;
    private final byte[] bytes;        // the rendered PDF payload
    final long nativeFontHandle;       // simulated native resource

    RenderedPdf(String accountId, byte[] bytes, long nativeFontHandle) {
        this.accountId = accountId;
        this.bytes = bytes;
        this.nativeFontHandle = nativeFontHandle;
    }

    String getAccountId() { return accountId; }
    int sizeBytes() { return bytes.length; }
}
