package com.bank.statement;

import java.lang.ref.SoftReference;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// Memory-sensitive cache: entries survive while memory is comfortable,
// and the GC clears them automatically under pressure.
class SoftPdfCache {
    private final Map<String, SoftReference<RenderedPdf>> cache = new ConcurrentHashMap<>();

    void put(String accountId, RenderedPdf pdf) {
        cache.put(accountId, new SoftReference<>(pdf));
    }

    // Returns the PDF, or null if the GC cleared it under memory pressure.
    RenderedPdf get(String accountId) {
        SoftReference<RenderedPdf> ref = cache.get(accountId);
        return ref == null ? null : ref.get();
    }
}
