package com.bank.statement;

import java.lang.ref.PhantomReference;
import java.lang.ref.Reference;
import java.lang.ref.ReferenceQueue;
import java.util.logging.Logger;

// Frees native font buffers AFTER their RenderedPdf is truly reclaimed.
// A phantom reference cannot access the referent; it only signals death.
class PhantomCleaner implements Runnable {
    private static final Logger log = Logger.getLogger(PhantomCleaner.class.getName());
    private final ReferenceQueue<RenderedPdf> queue = new ReferenceQueue<>();
    private volatile boolean running = true;

    // Subclass carries the native handle to free, since get() is always null.
    private static class FontRef extends PhantomReference<RenderedPdf> {
        final long nativeFontHandle;
        FontRef(RenderedPdf pdf, ReferenceQueue<RenderedPdf> q) {
            super(pdf, q);
            this.nativeFontHandle = pdf.nativeFontHandle;
        }
    }

    // keep the phantom refs reachable, else THEY get collected before firing
    private final java.util.Set<FontRef> tracked =
            java.util.Collections.synchronizedSet(new java.util.HashSet<>());

    void track(RenderedPdf pdf) {
        tracked.add(new FontRef(pdf, queue));
    }

    @Override public void run() {
        while (running) {
            try {
                Reference<? extends RenderedPdf> r = queue.remove(200);
                if (r instanceof FontRef fr) {
                    // pretend to free native memory
                    log.info(() -> "Freed native font handle " + fr.nativeFontHandle
                            + " after PDF was reclaimed (phantom post-mortem cleanup)");
                    tracked.remove(fr);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                running = false;
            }
        }
    }

    void stop() { running = false; }
}
