package com.bank.statement;

import java.lang.ref.WeakReference;
import java.math.BigDecimal;
import java.util.Map;
import java.util.WeakHashMap;
import java.util.logging.*;

public class ReferenceTypesDemo {
    private static final Logger log = Logger.getLogger(ReferenceTypesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        // STRONG: rajesh is kept alive for the whole method.
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        log.info(() -> "STRONG ref holds " + rajesh.getHolderName() + " alive.");

        // SOFT: cache a rendered PDF; survives until memory pressure.
        SoftPdfCache cache = new SoftPdfCache();
        cache.put("SAV2001", new RenderedPdf("SAV2001", new byte[64_000], 9001L));
        log.info(() -> "SOFT cache hit? " + (cache.get("SAV2001") != null));

        // WEAK: diagnostics keyed by account; vanish when key unreachable.
        Map<Account, String> diagnostics = new WeakHashMap<>();
        Account temp = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        diagnostics.put(temp, "renderLatencyMs=42");
        WeakReference<Account> weak = new WeakReference<>(temp);
        log.info(() -> "WEAK: diagnostics size before drop = " + diagnostics.size());
        temp = null; // drop the only strong ref to the key
        System.gc(); Thread.sleep(200);
        log.info(() -> "WEAK: key collected? " + (weak.get() == null)
                + ", diagnostics size now = " + diagnostics.size());

        // PHANTOM: free native font buffer after the PDF is reclaimed.
        PhantomCleaner cleaner = new PhantomCleaner();
        Thread cleanerThread = new Thread(cleaner, "phantom-cleaner");
        cleanerThread.setDaemon(true);
        cleanerThread.start();
        RenderedPdf disposable = new RenderedPdf("SAV2001", new byte[8_000], 9002L);
        cleaner.track(disposable);
        disposable = null; // now phantom-reachable after GC
        for (int i = 0; i < 5; i++) { System.gc(); Thread.sleep(200); }
        cleaner.stop();

        log.info(() -> "Rajesh still alive via STRONG ref: " + rajesh.getAccountId());
    }
}

